t.script:
window.dataLayer = window.dataLayer || [];
function gtag(){dataLayer.push(arguments);}
gtag('js', new Date());

gtag('config', 'G-Y6JMM9VCW2');

// Ticket availability — update the sold counts here as tickets sell.
(function(){
  var tiers=[
    {id:'tier-seb', total:5,  sold:0},
    {id:'tier-eb',  total:5,  sold:0},
    {id:'tier-full',total:10, sold:0}
  ];
  var activeSet=false;
  tiers.forEach(function(t){
    var card=document.getElementById(t.id); if(!card) return;
    var left=Math.max(0,t.total-t.sold);
    var fill=card.querySelector('.tk-fill'), label=card.querySelector('.tk-label'), btn=card.querySelector('.et_pb_button');
    if(fill) fill.style.width=Math.round(t.sold/t.total*100)+'%';
    if(left===0){
      card.classList.add('tier-soldout');
      if(label) label.textContent='Sold out';
      if(fill) fill.style.width='100%';
      if(btn){btn.style.pointerEvents='none';btn.style.opacity='.5';btn.textContent='Sold Out';}
    } else {
      if(label) label.textContent=left+' of '+t.total+' tickets left';
      if(!activeSet){card.classList.add('tier-active');activeSet=true;}
      else if(btn){btn.style.pointerEvents='none';btn.style.opacity='.45';btn.textContent='Opens After Previous Wave';}
    }
  });
})();
